  `scheduled_at` datetime NOT NULL,
  `status` enum('pending','confirmed','completed','cancelled') NOT NULL DEFAULT 'pending',
  `appointment_type` enum('regular','followup') NOT NULL DEFAULT 'regular',
  `followup_track` enum('monthly','quarterly') DEFAULT NULL,
  `followup_category` varchar(60) DEFAULT NULL,
  `source_measurement_id` int(10) UNSIGNED DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `location` varchar(150) DEFAULT 'Barangay Health Center',
