  `waz` decimal(5,2) DEFAULT NULL,
  `haz` decimal(5,2) DEFAULT NULL,
  `whz` decimal(5,2) DEFAULT NULL,
  `nutritional_status` enum('Normal','Moderately Underweight','Severely Underweight','Moderately Stunted','Severely Stunted','Moderately Wasted','Severely Wasted','Overweight','Obese') DEFAULT NULL,
